panel.addEventListener("click",ev=>{const b=ev.target.closest("[data-action]");if(!b)return;const a=b.dataset.action;const form=panel.querySelector(".sst-form");if(a==="Documentos Anexados"){openLibrary(true);}else if(a==="upload"){const dialog=document.createElement("dialog");dialog.className="sst-modern-dialog";dialog.innerHTML=`<form style="display:grid;gap:14px;padding:24px;width:min(480px,80vw)"><h3>Anexar documento</h3><p>Selecione o arquivo e a pasta de destino.</p><input type="file" name="arquivo" required accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg,.webp,.txt,.csv"><input name="titulo" placeholder="Título" required maxlength="200"><select name="categoria"><option>PGR</option><option>PCMSO</option><option>EPI</option><option>DDS</option><option>Outros</option></select><small>Até 25 MB</small><p role="status"></p><button type="submit">Enviar</button><button type="button">Cancelar</button></form>`;document.body.append(dialog);const f=dialog.querySelector("form");const send=f.querySelector("[type=submit]");send.disabled=true;categoryOptions().then(cats=>{f.elements.categoria.replaceChildren(...cats.map(c=>new Option(c,c)));send.disabled=false;}).catch(err=>{f.querySelector("[role=status]").textContent=err.message;});f.elements.arquivo.onchange=()=>f.elements.titulo.value=f.elements.arquivo.files[0]?.name.slice(0,200)||"";f.querySelector("[type=button]").onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();f.onsubmit=async ev=>{ev.preventDefault();const b=f.querySelector("[type=submit]");b.disabled=true;try{const r=await fetch(api+"/upload",{method:"POST",credentials:"same-origin",headers:{"X-Portal":"1"},body:new FormData(f)});if(!r.ok)throw Error("Falha no envio: "+r.status);f.querySelector("[role=status]").textContent="✓ Documento enviado com sucesso!";f.querySelector("[role=status]").style.color="#087d50";b.textContent="Enviado";f.querySelector("[type=button]").textContent="Fechar";await window.renderSST();}catch(err){f.querySelector("[role=status]").textContent=err.message;b.disabled=false;}};dialog.showModal();}else if(a==="epi"||a==="Cadastro de EPIs"){openEpi();}else if(a==="create"||a==="Modelos de Documentos"){if(form){form.hidden=false;if(a==="epi")form.elements.categoria.value="Retirada de EPI";form.scrollIntoView({block:"nearest"});form.elements.titulo.focus();}}else if(a==="signature"){openRequest();}else{status.textContent="Recurso ainda não integrado: "+a;}});
